function board(fen,{black=false,last=null,play=false,mini=false,label='Chess position'}={}){
  const cells={};let r=7,f=0;
  for(const c of fen.split(' ')[0]){if(c==='/'){r--;f=0}else if(/[1-8]/.test(c)){f+=Number(c)}else{cells['abcdefgh'[f]+(r+1)]=c;f++}}
  const ranks=black?[1,2,3,4,5,6,7,8]:[8,7,6,5,4,3,2,1];const files=black?'hgfedcba':'abcdefgh';
  const p=play?currentPractice():null;
  const legal=p&&state.selected&&!state.answer&&!state.revealed?p.candidates.filter(c=>c.uci.slice(0,2)===state.selected).map(c=>c.uci.slice(2,4)):[];
  let html=`<div class="board ${play?'playable':'static'}" ${play?'role="group"':'role="img"'} aria-label="${esc(label)}${black?', Black at bottom':', White at bottom'}">`;
  for(const [i,rank] of ranks.entries())for(const [j,file] of [...files].entries()){
    const sq=file+rank;const piece=cells[sq];const dark=(('abcdefgh'.indexOf(file)+rank)%2)===1;
    const classes=['square',dark?'dark':'',last&&(last.slice(0,2)===sq||last.slice(2,4)===sq)?'last':'',play&&state.selected===sq?'chosen':'',legal.includes(sq)?'target':''].filter(Boolean).join(' ');
    const names={p:'pawn',n:'knight',b:'bishop',r:'rook',q:'queen',k:'king'};
    const desc=piece?`${piece===piece.toUpperCase()?'White':'Black'} ${names[piece.toLowerCase()]}`:'empty';
    const open=play?`<button type="button" class="${classes}" data-action="square" data-square="${sq}" aria-label="${sq}, ${desc}" >`:`<div class="${classes}" data-board-square="${sq}">`;
    html+=open+(i===7&&!mini?`<span class="coord file">${file}</span>`:'')+(j===0&&!mini?`<span class="coord rank">${rank}</span>`:'')+(piece?`<img draggable="false" src="assets/${piece===piece.toUpperCase()?'w':'b'}${piece.toLowerCase()}.svg" alt="">`:'')+(play?'</button>':'</div>');
  }
  return html+'</div>';
}
