function drawRating(){
  const a=D.rating,min=Math.min(...a.map(x=>x.rating))-30,max=Math.max(...a.map(x=>x.rating))+30;
  const first=a[0].date,last=a[a.length-1].date;
  const points=a.map(x=>`${((x.date-first)/(last-first)*320).toFixed(1)},${(90-(x.rating-min)/(max-min)*80).toFixed(1)}`).join(' ');
  return `<svg class="rating-chart" viewBox="0 0 320 100" preserveAspectRatio="none" role="img" aria-label="Historical Lichess bullet rating, ${Math.min(...a.map(x=>x.rating))} to ${Math.max(...a.map(x=>x.rating))}. This is not a training outcome."><defs><linearGradient id="rating-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#7ca1c7" stop-opacity=".22"/><stop offset="100%" stop-color="#7ca1c7" stop-opacity="0"/></linearGradient></defs><path d="M0 30H320M0 65H320M0 95H320" stroke="#e2e4e8" stroke-width=".7"/><polygon points="0,100 ${points} 320,100" fill="url(#rating-fill)"/><polyline points="${points}" fill="none" stroke="#7a99b7" stroke-width="1.5" vector-effect="non-scaling-stroke"/></svg>`;
}
