function currentPractice(){const a=practiceDeck();return a[state.practiceIndex%a.length]}
function positionClass(p){
  const pieces=p.fen.split(' ')[0].replace(/[^a-z]/gi,'');
  const count=c=>[...pieces].filter(x=>x===c).length;
  if(!/[qQbBnN]/.test(pieces)&&count('r')===1&&count('R')===1)return 'Single rook vs. single rook';
  if(!/[qQbBnNrR]/.test(pieces))return 'King and pawn ending';
  if(p.category==='Endgames')return p.theme.replace(/^Endgame decision in /,'').replace(/^./,c=>c.toUpperCase());
  return /[qQ]/.test(pieces)?'Queens on the board':'Queenless position';
}
