function personalEvidence(p){
  if(p.category==='Endgames'){
    const single=D.summary.endgames.find(x=>x.kind==='Single rook versus single rook');
    const mixed=D.summary.endgames.find(x=>x.kind==='Rook with minor piece material');
    const row=positionClass(p)==='Single rook vs. single rook'?single:D.summary.endgames.find(x=>x.kind.toLowerCase()===p.theme.replace(/^Endgame decision in /,'').toLowerCase())||mixed;
    return `<div class="history-evidence"><span class="eyebrow">In your game history</span><strong>${row.checked_large_errors} / ${row.checked_competitive_moves}</strong><p>Large errors in eligible ${esc(row.kind.toLowerCase())} decisions (${pct(row.competitive_error_rate)}).</p>${row===single?`<p class="tiny">${row.checked_large_errors-row.errors_under_10_seconds} of these ${row.checked_large_errors} errors began with at least 10 seconds on the clock.</p>`:''}</div>`;
  }
  const row=D.summary.tactics.find(x=>x.motif===(p.category==='Defense'?'free_piece_capture':'mate_in_one'));
  return `<div class="history-evidence"><span class="eyebrow">In your game history</span><strong>${p.category==='Defense'?row.allowed:row.missed+' / '+row.opportunities}</strong><p>${p.category==='Defense'?'Checked errors that allowed a free-piece capture. Tactical labels can overlap.':'Missed mates in one across eligible opportunities.'}</p></div>`;
}
function learningRecord(){
  const ps=allPractice(),attempts=ps.map(p=>saved[p.id]).filter(x=>x&&x.correct!==null),right=attempts.filter(x=>x.correct).length,viewed=ps.filter(p=>saved[p.id]?.correct===null).length;
  return `<section class="learning-record"><h2>Your practice record</h2><div class="record-row"><span>Sound first moves</span><strong>${attempts.length?right+' / '+attempts.length:'—'}</strong><p>${attempts.length?'First unassisted attempts across all priorities.':'Move a piece to begin.'}</p></div><div class="record-row"><span>Solutions opened</span><strong>${viewed}</strong><p>Excluded from the first-attempt score.</p></div><p class="record-note">Saved in this browser. Retries don’t change the score. Practice results do not yet tell us whether decisions improved in later games.</p></section>`;
}
function practice(){
  const deck=practiceDeck(),p=currentPractice(),a=state.answer,reveal=!!a||state.revealed;
  const seq=a?a.line:p.best,step=Math.min(state.practiceLineStep,seq.length-1),frame=reveal?seq[step]:seq[0];
  return heading('Practice','Your next move.','Start with a priority from your games. Move a piece on the board to see the feedback.')+
  `<section class="practice-priorities" aria-label="Practice priorities">${priorities.map((x,i)=>`<button class="priority-choice ${state.practiceFilter===x.key?'active':''}" data-action="practice-filter" data-filter="${x.key}" aria-pressed="${state.practiceFilter===x.key}"><span class="priority-number">0${i+1}</span><strong>${x.name}</strong><span>${x.note}</span><small>${x.evidence}</small></button>`).join('')}</section>
  <div class="practice-session-head"><h2>${priorities.find(x=>x.key===state.practiceFilter)?.name||'All positions'}</h2><button class="text-link" data-action="practice-filter" data-filter="All">All 26 positions ${icon('arrow')}</button></div>
  <section class="practice-layout"><div><div class="board-area">${playerBar(p,false,true)}${board(frame.fen,{black:state.flip?p.color==='white':p.color==='black',last:reveal?frame.uci:null,play:!reveal,label:reveal?'Checked continuation':`${p.color} to move, practice position`})}${playerBar(p,true,true)}<div class="board-controls"><span class="small muted">${reveal?'Checked continuation':`${p.color==='white'?'White':'Black'} to move`}</span><button class="icon-btn" data-action="flip" aria-label="Flip board">${icon('flip')}</button></div></div><p class="tiny board-instruction">${reveal?`${ext(source(p),'Original game')} · historical move: ${esc(p.played)}`:'Drag a piece, or select a piece and its destination. Keyboard: arrows to navigate, Enter to select.'}</p></div>
  <div class="panel practice-panel"><div class="practice-count">Position ${state.practiceIndex%deck.length+1} of ${deck.length}<span style="float:right">${p.color==='white'?'White':'Black'} to move</span></div><div class="progress-track"><span style="width:${(state.practiceIndex%deck.length)/deck.length*100}%"></span></div><div class="position-class">${tag(positionClass(p))}${tag(p.speed+' · '+p.timeControl)}</div><h2>${reveal?(a?.sound?'A sound move.':a?'Compare the lines.':'Compare the continuations.'):'What would you play?'}</h2><p>${reveal?esc(p.title):'Choose your move on the board. Sound alternatives to the engine’s top choice also count.'}</p>
  ${!reveal?`<div class="board-prompt">${icon('board')}<div><strong>${state.selected?'Choose a destination':'Your move'}</strong><p>${state.selected?'The dots show legal squares for this piece.':'Select or drag one of your pieces to begin.'}</p></div></div>${state.promotion?`<p class="small muted">Promote to:</p><div class="promotion-options">${state.promotion.map(c=>`<button class="btn" data-action="submit-uci" data-uci="${c.uci}" aria-label="Promote to ${c.uci[4]}"><img src="assets/${p.color==='white'?'w':'b'}${c.uci[4]}.svg" alt="">${esc(c.san)}</button>`).join('')}</div>`:''}<div class="error-message" role="status">${esc(state.practiceError)}</div>${personalEvidence(p)}`:
  `<div class="feedback ${a&&!a.sound?'bad':''}" role="status"><div class="eyebrow">Decision to practice</div><p class="classified-theme">${esc(decisionThemes[p.id]||p.theme)}</p><h3>${a?`${esc(a.san)} · ${a.sound?'sound':'compare with '+esc(p.bestSan)}`:`Engine choice · ${esc(p.bestSan)}`}</h3><p>${esc(p.explanation)}</p><p style="margin-top:15px"><strong>Next time:</strong> ${esc(p.takeaway)}</p><p class="tiny" style="margin-top:15px">${a?`Evaluation after ${esc(a.san)}: ${evalStr(a.cp,a.mate)} for your side. `:''}Original clock: ${p.clock.toFixed(2)}s.</p><div class="moves" style="margin-top:20px" aria-label="Your move’s checked continuation">${seq.map((m,i)=>`<button data-action="practice-step" data-to="${i}" class="${i===step?'active':''}">${i===0?'Start':esc(m.san)}</button>`).join('')}</div>${D.positions.some(x=>x.id===p.id)?link('#explore?id='+p.id,'Compare with the historical move'):ext(source(p),'View original game')}</div>`}
  <div class="practice-utilities">${reveal?`<button class="btn" data-action="retry">Try another move</button>`:`<button class="btn" data-action="reveal">Show the line</button>`}<button class="btn primary" data-action="next-practice">Next position ${icon('arrow')}</button></div><span class="saved-note">${saved[p.id]?(saved[p.id].correct===null?'Solution viewed. Excluded from your score.':'First attempt recorded. Retrying won’t change your score.'):'Your first unassisted attempt will be saved.'}</span></div></section>
  ${learningRecord()}
  <details class="method-details"><summary>How practice is built <span>+</span></summary><p>These 26 positions come from the analyzed archive. Material labels are derived from the board; decision themes and coaching notes combine checked engine lines with authored explanations. The personal risk model is separate from these labels. Historical rates describe this archive, not a comparison with other players.</p><p>Every legal first move was evaluated offline using Stockfish 19 at 100,000 nodes per candidate. Sound means within 3 percentage points of the best checked evaluation-proxy score. If an immediate mate exists, your move must also mate. These are finite-search estimates, not personal win probabilities.</p><p>Only the first unassisted attempt counts. Opening a solution excludes that position. Measuring improvement in play would require unfamiliar positions and later games; this practice session alone cannot establish it.</p><button class="btn small" data-action="reset-progress" style="margin-top:22px">Reset browser practice progress</button></details>`;
}
const featureLabels={move_number:'Move number',own_material:'Own material',opponent_material:'Opponent material',material_balance:'Material balance',pieces_on_board:'Pieces on board',own_pawns:'Own pawns',opponent_pawns:'Opponent pawns',log_legal_moves:'Legal move count',in_check:'In check',endgame:'Endgame',opening:'Opening phase',queens_on_board:'Queens on board',rooks_on_board:'Rooks on board',king_distance:'King distance',log_clock_before:'Clock remaining',clock_fraction:'Clock fraction',under_10_seconds:'Under 10 seconds',increment_seconds:'Increment',rating_difference:'Rating difference',as_white:'Playing White',pre_eval_proxy:'Pre-move evaluation proxy'};
function modelScore(x){return 1/(1+Math.exp(-D.model.intercept-x.reduce((s,v,i)=>s+(v-D.model.means[i])/D.model.scales[i]*D.model.coefficients[i],0)))}
function modelFeatures(p,cb){const x=[...p.features];x[14]=Math.log1p(Math.max(0,cb));x[15]=Math.max(0,cb)/Math.max(1,p.initialClock);x[16]=+(cb<10);return x}
function contributions(x){return x.map((v,i)=>({name:featureLabels[D.model.feature_names[i]],v:(v-D.model.means[i])/D.model.scales[i]*D.model.coefficients[i]})).sort((a,b)=>Math.abs(b.v)-Math.abs(a.v)).slice(0,5)}
function model(){
  const e=D.evaluation,p=D.heldout[state.modelIndex],cb=state.modelClock??p.clock,x=modelFeatures(p,cb),risk=modelScore(x),c=contributions(x),max=Math.max(...c.map(x=>Math.abs(x.v)));
  const reduction=(e.constant_baseline.log_loss-e.test.log_loss)/e.constant_baseline.log_loss;
  return heading('The model','Predicting errors in my bullet games','Logistic regression using 21 pre-move features, evaluated on a later set of games.',tag('L2 logistic regression','neutral'))+
  `<section class="stats-row model-stats">${stat('Test-set ROC AUC','0.689','Ranking quality · 0.5 is chance','model')}${stat('Test-set log loss','0.304','Lower is better · baseline 0.324','chart')}${stat('Versus constant baseline',pct(reduction),'Relative reduction in test log loss','target')}${stat('Held-out decisions','3,765','375 engine-labeled errors','board')}</section>
  <section class="method-split"><div class="panel"><h3>${icon('board')} 1. Classify the chess pattern</h3><p>Engine continuations plus explicit chess rules flag motifs such as mates, forks and pins. Endgames are grouped by material. The motif categories are defined by chess rules.</p></div><div class="panel"><h3>${icon('model')} 2. Learn personal error risk</h3><p>The trained classifier uses 21 pre-move features, including material, legal move count, phase, clock and engine evaluation. It predicts whether the next decision crosses an engine-defined error threshold.</p></div></section>
  <div class="section-head"><div><h2>Chronological evaluation</h2><p>Chronological split by whole games · 589 standard bullet games</p></div><span class="tiny">No test-game moves used to fit the model</span></div><div class="phase-strip"><div><strong>353 games</strong><span>TRAIN · fit feature scaling and model</span></div><div><strong>118 games</strong><span>VALIDATE · select L2 penalty</span></div><div><strong>118 games</strong><span>TEST · evaluate once</span></div></div>
  <section class="panel"><div class="section-head"><div><h2>Inspect a prediction</h2><p>50 held-out examples spread across the observed risk range.</p></div>${tag('Saved model coefficients')}</div><div class="model-interactive"><div class="model-board-wrap"><div class="player-bar"><span class="small muted">${p.color==='white'?'White':'Black'} to move · move ${Math.ceil(p.ply/2)}</span>${ext(source(p),'Source game')}</div>${board(p.fen,{black:p.color==='black',label:'Held-out model example'})}<div class="board-source"><span>${fmtDate(p.date)}</span><span>Historical clock: ${p.clock.toFixed(2)}s</span></div></div><div class="model-controls"><label for="model-position">Choose a held-out position</label><select id="model-position">${D.heldout.map((q,i)=>`<option value="${i}" ${i===state.modelIndex?'selected':''}>${i+1}. ${q.gameId} · move ${Math.ceil(q.ply/2)} · ${pct(q.risk)} fitted risk</option>`).join('')}</select><div class="risk-readout"><div><p>FITTED ENGINE-ERROR RISK</p><strong id="risk-value">${pct(risk)}</strong></div><small>Uncalibrated estimate<br>for this player’s bullet games</small></div><div class="risk-track"><span id="risk-bar" style="width:${risk*100}%"></span></div><div class="range-label"><label for="model-clock">Change the clock feature</label><strong id="clock-value">${cb.toFixed(2)}s</strong></div><input type="range" id="model-clock" min="0" max="${Math.max(180,p.initialClock+30,p.clock)}" step="0.01" value="${cb}" aria-describedby="clock-caveat"><p class="tiny" id="clock-caveat">The slider changes three clock features and holds the board position fixed. The resulting score describes the model’s response; the archive cannot show how extra thinking time would have changed this move.</p><button class="text-link" style="border:0;background:transparent;padding:8px 0;font-size:10px" data-action="reset-clock">Restore original clock ↺</button><div class="model-outcome">${state.modelOutcome?`<p>${tag(p.actual?'Engine-labeled error':'Below error threshold',p.actual?'warning':'')}<br><span class="tiny">Historical move: ${esc(p.played)}. This outcome belongs to the original clock.</span></p>`:`<p>Did this historical move cross the engine-error threshold?</p><button class="btn small" data-action="model-outcome">Reveal outcome</button>`}</div><div class="contributions"><h3>Largest contributions for this position</h3><div id="contribution-bars">${contributionHTML(c,max)}</div><p class="tiny">Standardized feature contributions in log odds, relative to the training mean. The intercept is ${D.model.intercept.toFixed(2)}.</p></div></div></div></section>
  <section class="model-bottom"><div class="panel"><div class="section-head"><div><h2>Held-out comparison</h2><p>Same 3,765 decisions for every model</p></div></div><div class="evidence-table-wrap"><table class="data-table"><thead><tr><th>Model</th><th>ROC AUC ↑</th><th>Log loss ↓</th></tr></thead><tbody><tr><td>Constant training error rate</td><td>0.500</td><td>${e.constant_baseline.log_loss.toFixed(3)}</td></tr><tr><td>Clock-only baseline</td><td>${e.clock_baseline.auc.toFixed(3)}</td><td>${e.clock_baseline.log_loss.toFixed(3)}</td></tr><tr class="emphasis"><td>Personal classifier</td><td>${e.test.auc.toFixed(3)}</td><td>${e.test.log_loss.toFixed(3)}</td></tr></tbody></table></div><p class="tiny" style="margin-top:14px;line-height:1.9">AUC measures ranking: an error turn tends to receive higher risk than a non-error turn. 0.689 is not 68.9% classification accuracy. Most turns are non-errors, making raw accuracy a misleading headline.</p></div><div class="panel"><div class="section-head"><div><h2>Risk groups vs. actual errors</h2><p>All held-out turns, sorted into ten equal-size groups</p></div></div><div class="model-chart" role="img" aria-label="Predicted and observed error rates by risk decile">${D.riskBins.map((b,i)=>`<div class="bucket" title="Group ${i+1}: ${b.n} turns, ${pct(b.risk)} predicted, ${pct(b.errorRate)} observed"><i style="height:${b.risk/.4*100}%"></i><i class="actual" style="height:${b.errorRate/.4*100}%"></i><small>${i+1}</small></div>`).join('')}</div><div class="chart-legend"><span>Mean predicted risk</span><span>Observed error rate</span></div><p class="tiny" style="margin-top:13px">Descriptive test-set check. No post-hoc calibration was fitted.</p></div></section>
  <details class="method-details"><summary>Data, labels, reproducibility and limitations <span>+</span></summary><p><strong>Archive.</strong> 619 completed public games from Nov 4, 2025 to Nov 4, 2026; one King of the Hill game excluded. 618 standard games yield 20,537 player turns. The model uses only 589 standard bullet games. Blitz, rapid and over-the-board performance are outside its validated scope.</p><p><strong>Target.</strong> A decline of at least 10 percentage points in a fixed centipawn-to-win-proxy transform after the player’s move. Stockfish 19 generated the original labels at 12,000 nodes per position. The transform is an evaluation proxy, not a calibrated personal win probability. All 5,529 endgame decisions and selected tactical screens were rechecked within 8,724 positions at 100,000 nodes. Motif counts and model labels therefore come from different analysis stages.</p><p><strong>Fitting.</strong> Features are calculated from the board and clock before the move. Feature means and scales come only from training games. Validation log loss selected the L2 penalty from four candidates. The classifier does not use the actual chosen move or the resulting evaluation as input. The pre-move engine evaluation is an input, so fresh inference on arbitrary new positions would need an engine.</p><p><strong>Limits.</strong> Finite engine search can mislabel moves. Turns within games are correlated; familiar opening positions may recur across different games. This is one player’s archive, with no peer benchmark, causal diagnosis or demonstrated training effect. A future check would use a new time period and exclude near-duplicate positions.</p><div class="downloads"><a class="text-link" href="assets/risk-model.json" download>${icon('download')} Saved coefficients</a><a class="text-link" href="assets/model-evaluation.json" download>${icon('download')} Full evaluation</a><a class="text-link" href="assets/targeted-practice.pgn" download>${icon('download')} Practice PGN</a></div></details>`;
}
function contributionHTML(c,max){return c.map(t=>`<div class="contribution ${t.v<0?'negative':''}"><span>${esc(t.name)}</span><span class="bar"><i style="width:${Math.abs(t.v)/max*100}%"></i></span><strong>${t.v>0?'+':''}${t.v.toFixed(2)}</strong></div>`).join('')}
function flowImage(kind){
 const frame='<rect x="18" y="12" width="204" height="122" rx="13" fill="white" stroke="#dedee3"/>';
 const chess='<g transform="translate(71 27)">'+Array.from({length:16},(_,i)=>`<rect x="${i%4*25}" y="${Math.floor(i/4)*25}" width="25" height="25" fill="${(i%4+Math.floor(i/4))%2?'#a3aaa5':'#eeede9'}"/>`).join('')+'<image href="assets/wk.svg" x="0" y="75" width="25" height="25"/><image href="assets/br.svg" x="75" y="0" width="25" height="25"/>';
 const scenes={
 identify:frame+'<rect x="36" y="31" width="57" height="7" rx="3" fill="#c6c6cc"/><rect x="36" y="53" width="168" height="19" rx="5" fill="#eaf3ff"/><rect x="44" y="59" width="82" height="6" rx="3" fill="#0071e3"/><rect x="36" y="84" width="107" height="6" rx="3" fill="#c6c6cc"/><rect x="36" y="104" width="71" height="6" rx="3" fill="#dedee3"/><circle cx="191" cy="62" r="5" fill="#0071e3"/>',
 practice:frame+chess+'<rect x="25" y="50" width="25" height="25" fill="#c9dcec"/><image href="assets/wr.svg" x="25" y="50" width="25" height="25"/><path d="M38 43V18m-6 6 6-6 6 6" fill="none" stroke="#0071e3" stroke-width="2.5" stroke-linecap="round"/></g>',
 assess:frame+chess+'<image href="assets/wr.svg" x="0" y="25" width="25" height="25"/><circle cx="62" cy="62" r="8" fill="#0071e3" opacity=".25"/></g><circle cx="194" cy="110" r="17" fill="#0071e3"/><path d="m186 110 5 5 10-11" fill="none" stroke="white" stroke-width="2.5" stroke-linecap="round"/>',
 followup:frame+'<path d="M40 33v80h160" fill="none" stroke="#dedee3" stroke-width="1.5"/><path d="m43 46 32 13 30-4 31 25 31 8 32 16" fill="none" stroke="#0071e3" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/><circle cx="43" cy="46" r="4" fill="#0071e3"/><circle cx="199" cy="104" r="4" fill="#0071e3"/>'
 };
 return `<svg class="flow-image" viewBox="0 0 240 148" role="img" aria-label="${{identify:'A recurring error selected from game history',practice:'A rook moving to an active square',assess:'A new chess position with a first-attempt check',followup:'Illustration of the intended decline in later-game errors, not measured results'}[kind]}">${scenes[kind]}</svg>`;
}
function product(){
  const learners=10000,plans=40000,variable=1200,fixed=1800,total=3000,extra=learners*state.caseLift/100;
  const money=n=>'$'+num(n);
  return heading('Lichess · Business case','A learning plan after game review','An optional practice plan for Lichess. The pilot would measure learning and repeat use against an agreed operating budget.')+
  `<nav class="case-nav" aria-label="Case contents">${[['case-problem','Problem'],['case-goals','Goals'],['case-edge','Strategy'],['case-pilot','Pilot'],['case-economics','Economics'],['case-decision','Decision']].map(([id,t])=>`<button data-action="case-jump" data-target="${id}">${t}</button>`).join('')}</nav>
  <section class="product-hero" id="case-problem"><div><div class="eyebrow">The problem to validate</div><h2>Choosing what to practice next</h2><p>Lichess already helps me examine a mistake. I still need to decide what to practice afterward. I built this prototype to turn recurring errors in my games into focused practice. I would first investigate how often other players encounter the same problem.</p></div><div class="quote">Proposed first release<small>A rook-ending practice plan linked from completed-game analysis, with assessment positions drawn from different games.</small></div></section>
  <section class="strategy-grid"><div class="panel"><span class="section-number">The first customer</span><h3>Frequent players with recurring errors</h3><p>The first users would already review games and have enough relevant positions for a plan. I would interview players and observe review sessions to learn how they currently choose practice. The size of this audience is still unknown.</p></div><div class="panel"><span class="section-number">What the archive showed</span><h3>Rook decisions with time remaining</h3><p>I found 53 large errors in competitive single-rook positions. Of those, 38 began with at least 10 seconds remaining, and the engine preferred a quiet king or rook move in 30 cases. These positions give me material for a rook-ending plan. Clock readings alone cannot establish why I missed a move.</p></div></section>
  <section id="case-goals"><div class="section-head"><div><h2>Goals and measures</h2><p>Lichess is a donation-supported nonprofit. The proposal needs a learning benefit that is worth its development and running costs.</p></div></div><div class="evidence-table-wrap"><table class="data-table competitor-table"><thead><tr><th>Priority</th><th>What to measure</th><th>Why it matters</th></tr></thead><tbody><tr><td>Learning</td><td>Target errors ÷ eligible decisions in later games, compared with a control group and the prior period.</td><td>Check whether the skill carries into play. Puzzle completion alone is insufficient.</td></tr><tr><td>Repeat use</td><td>Assigned eligible players who make a qualifying learning attempt in week four ÷ all assigned eligible players.</td><td>Test whether the service creates a useful learning habit. More screen time is not the objective.</td></tr><tr><td>Sustainability</td><td>Monthly operating cost, cost per active learner, and cost per incremental retained learner.</td><td>Keep the service affordable within an approved donation-funded budget.</td></tr><tr><td>Trust and access</td><td>Explanation errors, opt-outs, page latency and accessibility issues; preserve zero-price access.</td><td>Protect the reasons people choose Lichess in the first place.</td></tr></tbody></table></div><p class="competitive-note">Patrons fund Lichess while features remain free. I would budget this service on that basis. Any increase in donations would need to be measured separately. ${ext('https://lichess.org/patron','Lichess funding model')}</p></section>
  <section id="case-edge" style="margin-top:55px"><div class="section-head"><div><h2>Existing tools and competitors</h2><p>The plan would reuse existing analysis and practice content.</p></div></div><div class="evidence-table-wrap"><table class="data-table competitor-table"><thead><tr><th>Product</th><th>Existing strength</th><th>Implication for this proposal</th></tr></thead><tbody><tr><td>${ext('https://lichess.org/features','Lichess')}</td><td>Analysis, Insights, learning from mistakes, puzzles, practice and studies are already available without a feature paywall.</td><td>The additional work is choosing a relevant next task from recurring errors and showing why it was recommended.</td></tr><tr><td>${ext('https://support.chess.com/en/articles/8584089-how-does-game-review-work','Chess.com')}</td><td>Guided review, retries and relevant course recommendations.</td><td>Players already have guided review elsewhere. The proposed Lichess plan would need to be easy to use within its existing review flow.</td></tr></tbody></table></div><p class="competitive-note">The prototype offers 26 positions organized around three priorities from my games. Retries cannot improve the first-attempt score. A pilot would add unfamiliar assessment positions and follow later games to test whether practice changes decisions in play.</p></section>
  <section class="learning-flow" aria-label="Proposed learning flow">${[
 ['Identify','Find a recurring decision','History → one clear priority',flowImage('identify')],
 ['Practice','Work on the idea','Positions from your games',flowImage('practice')],
 ['Assess','Try an unfamiliar position','First attempts, scored separately',flowImage('assess')],
 ['Follow up','Look at later games','Fewer errors per eligible decision',flowImage('followup')]
].map(([label,title,note,img],i)=>`<div class="learning-flow-step">${img}<span class="flow-label">0${i+1} · ${label}</span><h3>${title}</h3><p>${note}</p>${i<3?`<span class="flow-arrow" aria-hidden="true">${icon('arrow')}</span>`:''}</div>`).join('')}</section>

  <section class="strategy-grid"><div class="panel"><span class="section-number">Technical scope</span><h3>Why I used rules and a small model</h3><p>I used chess rules and engine continuations to label patterns. A separate logistic model estimates error risk in my bullet games, with a test ROC AUC of 0.689. I would start the pilot with rule-based recommendations and use the classifier only if it selects more useful practice at an acceptable cost.</p>${link('#model','Inspect the model and baselines')}</div><div class="panel"><span class="section-number">Delivery and opportunity cost</span><h3>How the plan would fit into Lichess</h3><p>Use an optional next-step prompt after completed-game analysis. Reuse cached analysis and vetted lessons; avoid reanalyzing every historical game on page load. A pilot competes with other learning improvements and essential platform maintenance for finite engineering and funding capacity.</p></div></section>
  <section class="experiment" id="case-pilot"><div class="eyebrow">The pilot</div><h2>Pilot design</h2><p>Recruit consenting, frequent players with enough relevant history. Randomly assign them to the existing Lichess review experience or review plus the focused plan and separate assessments. Stratify by baseline rating and time control. Set the follow-up window, meaningful effect size and cost limit before launch.</p><div class="experiment-grid"><div><h3>Primary evidence</h3><p>Compare target errors per eligible later decision, with player-level uncertainty. Report missing follow-up and opportunity counts. Use fresh-position results as supporting evidence, not proof of game improvement.</p></div><div><h3>Adoption and return</h3><p>Track the funnel: eligible → offered → started → completed → returned in week four. Compare return on all assigned players, rather than only enthusiastic completers.</p></div><div><h3>Decision rule</h3><p>Expand only if the learning benefit is meaningful and credible, use is sustained, and cost and trust limits hold. If uptake is low, investigate relevance and discoverability. If scores rise only on repeats, redesign the training.</p></div></div></section>
  <section id="case-economics" style="margin-top:55px"><div class="section-head"><div><h2>Operating cost</h2><p>Illustrative figures. Lichess’s actual operating costs have not been estimated here.</p></div></div><div class="economics" style="margin-top:26px"><div class="panel"><h3>Monthly cost assumptions</h3><p>Assume 10,000 active feature learners, four plans per month, $0.03 marginal analysis cost per plan, and $1,800 in monthly maintenance and content cost.</p><table class="data-table" style="margin-top:18px"><tbody><tr><td>Monthly plans</td><td>${num(plans)}</td></tr><tr><td>Variable cost · 40,000 × $0.03</td><td>${money(variable)}</td></tr><tr><td>Monthly fixed cost</td><td>${money(fixed)}</td></tr><tr class="emphasis"><td>Total monthly cost</td><td>${money(total)}</td></tr></tbody></table><p class="tiny">This omits one-time development cost, which must also fit the pilot budget. Real marginal costs need profiling and a sensitivity check.</p></div><div class="panel"><h3>Cost per additional returning learner</h3><p>Assume four-week learning return would otherwise be 25%. Change the assumed lift to see the cost per incremental returning learner in this monthly cohort.</p><div class="segmented" style="margin-top:20px" aria-label="Assumed retention lift">${[2,5,8].map(v=>`<button data-action="case-lift" data-lift="${v}" class="${state.caseLift===v?'active':''}" aria-pressed="${state.caseLift===v}">+${v} percentage points</button>`).join('')}</div><div class="planning-result"><div><strong>${num(extra)}</strong><span>extra week-four returning learners</span></div><div><strong>$${(total/extra).toFixed(2)}</strong><span>monthly cost per incremental returner</span></div></div><p class="small">Return rises from 25% to ${25+state.caseLift}%, an assumed gain of ${state.caseLift} percentage points. At $5 net per recurring donor-month, $3,000 would require 600 donor-months of funding. That budget could come from existing support. Additional donations would require a separate estimate.</p></div></div></section>
  <section class="overview-bottom" id="case-decision"><div><h3>Recommendation</h3><p>Run an opt-in pilot focused on rook-ending decisions, using existing analysis. Expand if players make fewer target errors in later games, continue to use the service, and the cost stays within the agreed budget. If improvement appears only on repeated positions, revise the lessons before expanding.</p></div>${link('#practice','Try the prototype')}</section>
  <details class="method-details"><summary>Sources and evidence boundaries <span>+</span></summary><p>The game analysis is complete. Customer research and the proposed pilot have not been conducted. Cost inputs are assumptions, and the prototype is separate from the Lichess service.</p><div class="source-list">${ext('https://lichess.org/page/about','Lichess · mission and operation')}${ext('https://lichess.org/features','Lichess · existing tools')}${ext('https://lichess.org/patron','Lichess · nonprofit funding and Patron access')}${ext('https://support.chess.com/en/articles/8584089-how-does-game-review-work','Chess.com · Game Review')}</div><p class="tiny">Sources checked November 2026. Independent proposal; no affiliation with or endorsement by these organizations.</p></details>`;
}
function render(){
  $('#navigation').innerHTML=nav.map(([id,name,ic])=>`<a href="#${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''} title="${name}">${icon(ic)}<span>${name}</span></a>`).join('');
  $('#page-name').textContent=page==='practice'?'Practice':nav.find(n=>n[0]===page)?.[1]||'Overview';
  document.title=`${$('#page-name').textContent} — Chess Insight`;
  $('#content').innerHTML=`<div class="page-enter">${({overview,explore:explorer,practice,model,product}[page]||overview)()}</div>`;
}
function route(){stopHomeAnimation();const [name,query]=(location.hash.slice(1)||'overview').split('?');page=name==='practice'||nav.some(x=>x[0]===name)?name:'overview';const params=new URLSearchParams(query||'');
  if(page==='explore'){state.exploreId=params.get('id')||state.exploreId;state.filter=params.get('filter')||'All';state.branch='best';state.step=0;state.flip=false}
  if(page==='practice'){state.practiceFilter=priorities.some(x=>x.key===params.get('focus'))?params.get('focus'):'Endgames';state.practiceIndex=0;const id=params.get('id');if(id){state.practiceFilter='All';const idx=practiceDeck().findIndex(p=>p.id===id);if(idx>=0)state.practiceIndex=idx}resetPractice();state.flip=false}
  render();window.scrollTo(0,0);if(page==='overview')playHomeAnimation();
}
function resetPractice(){state.practiceLineStep=1;state.selected=null;state.answer=null;state.revealed=false;state.practiceError='';state.promotion=null}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('toast-visible');setTimeout(()=>$('#toast').classList.remove('toast-visible'),2500)}
function submitMove(c){if(!c||state.answer||state.revealed)return;state.answer=c;state.selected=null;state.promotion=null;state.practiceError='';const p=currentPractice();if(!saved[p.id]){saved[p.id]={correct:c.sound,at:new Date().toISOString()};persist()}render()}
function chooseSquare(sq){if(page!=='practice'||state.answer||state.revealed)return;const p=currentPractice();if(state.selected){const options=p.candidates.filter(c=>c.uci.slice(0,2)===state.selected&&c.uci.slice(2,4)===sq);if(options.length===1){submitMove(options[0]);return}if(options.length>1){state.promotion=options;render();return}}
  state.selected=p.candidates.some(c=>c.uci.startsWith(sq))?sq:null;state.promotion=null;render();document.querySelector(`[data-square="${sq}"]`)?.focus({preventScroll:true});
}
document.addEventListener('click',ev=>{if(ev.target.closest('.skip-link')){ev.preventDefault();$('#content').focus();return}const t=ev.target.closest('[data-action]');if(!t||t.disabled||!D)return;const a=t.dataset.action;
  if(a==='case-jump'){document.getElementById(t.dataset.target)?.scrollIntoView({behavior:'smooth',block:'start'});return}
  if(a==='case-lift'){state.caseLift=Number(t.dataset.lift);render()}
  if(a==='home-choice'){stopHomeAnimation();state.homeArrived=true;state.homeChoice=t.dataset.choice;render()}
  if(a==='practice-step'){state.practiceLineStep=Number(t.dataset.to);render()}
  if(a==='filter'){state.filter=t.dataset.filter;state.step=0;render()}
  if(a==='position'){state.exploreId=t.dataset.id;state.step=0;state.branch='best';render();$('.explorer-layout')?.scrollIntoView({block:'start',behavior:'smooth'})}
  if(a==='branch'){state.branch=t.dataset.branch;state.step=0;render()}
  if(a==='step'){state.step=Number(t.dataset.to);render()}
  if(a==='flip'){state.flip=!state.flip;render()}
  if(a==='practice-filter'){state.practiceFilter=t.dataset.filter;state.practiceIndex=0;resetPractice();render()}
  if(a==='square'&&Date.now()>suppressBoardClickUntil){chooseSquare(t.dataset.square)}
  if(a==='submit-uci'){submitMove(currentPractice().candidates.find(c=>c.uci===t.dataset.uci))}
  if(a==='next-practice'){state.practiceIndex=(state.practiceIndex+1)%practiceDeck().length;resetPractice();render()}
  if(a==='reveal'){state.revealed=true;const p=currentPractice();if(!saved[p.id]){saved[p.id]={correct:null,at:new Date().toISOString()};persist()}render()}
  if(a==='retry'){resetPractice();render()}
  if(a==='reset-progress'){saved={};persist();resetPractice();render();toast('Practice progress reset in this browser.')}
  if(a==='model-outcome'){state.modelOutcome=true;render()}
  if(a==='reset-clock'){state.modelClock=null;render()}
});
document.addEventListener('change',ev=>{if(ev.target.id==='speed-filter'){state.speed=ev.target.value;state.step=0;render()}if(ev.target.id==='model-position'){state.modelIndex=Number(ev.target.value);state.modelClock=null;state.modelOutcome=false;render()}});
document.addEventListener('input',ev=>{if(ev.target.id!=='model-clock')return;state.modelClock=Number(ev.target.value);const p=D.heldout[state.modelIndex],x=modelFeatures(p,state.modelClock),v=modelScore(x),c=contributions(x);$('#risk-value').textContent=pct(v);$('#risk-bar').style.width=pct(v);$('#clock-value').textContent=state.modelClock.toFixed(2)+'s';$('#contribution-bars').innerHTML=contributionHTML(c,Math.max(...c.map(t=>Math.abs(t.v))))});
document.addEventListener('keydown',ev=>{if(page!=='explore'||/INPUT|SELECT|TEXTAREA/.test(ev.target.tagName)||!['ArrowLeft','ArrowRight','Home','End'].includes(ev.key))return;ev.preventDefault();const length=selectedPosition()[state.branch].length;state.step=ev.key==='Home'?0:ev.key==='End'?length-1:Math.max(0,Math.min(length-1,state.step+(ev.key==='ArrowRight'?1:-1)));render()});
let boardDrag=null,suppressBoardClickUntil=0;
function clearBoardDrag(){if(!boardDrag)return;boardDrag.ghost?.remove();boardDrag.anchor.classList.remove('drag-source');try{boardDrag.anchor.releasePointerCapture(boardDrag.id)}catch{}boardDrag=null}
document.addEventListener('pointerdown',ev=>{const el=ev.target.closest('.board.playable [data-square]');if(!el||ev.button!==0||!D||page!=='practice')return;const from=el.dataset.square;if(!currentPractice().candidates.some(c=>c.uci.startsWith(from)))return;boardDrag={from,x:ev.clientX,y:ev.clientY,id:ev.pointerId,anchor:el,ghost:null};el.setPointerCapture(ev.pointerId)});
document.addEventListener('pointermove',ev=>{const d=boardDrag;if(!d||ev.pointerId!==d.id)return;if(!d.ghost&&Math.hypot(ev.clientX-d.x,ev.clientY-d.y)>6){d.ghost=d.anchor.querySelector('img').cloneNode();d.ghost.className='drag-piece';d.ghost.style.width=d.anchor.clientWidth+'px';d.ghost.setAttribute('aria-hidden','true');document.body.append(d.ghost);d.anchor.classList.add('drag-source');document.querySelectorAll('.board .square').forEach(el=>{el.classList.toggle('chosen',el.dataset.square===d.from);el.classList.toggle('target',currentPractice().candidates.some(c=>c.uci.startsWith(d.from)&&c.uci.slice(2,4)===el.dataset.square))})}if(d.ghost){ev.preventDefault();d.ghost.style.left=ev.clientX+'px';d.ghost.style.top=ev.clientY+'px'}});
document.addEventListener('pointerup',ev=>{const d=boardDrag;if(!d||ev.pointerId!==d.id)return;const moved=!!d.ghost,from=d.from,to=document.elementFromPoint(ev.clientX,ev.clientY)?.closest('.board.playable [data-square]')?.dataset.square;clearBoardDrag();if(moved){suppressBoardClickUntil=Date.now()+300;state.selected=from;if(to&&currentPractice().candidates.some(c=>c.uci.startsWith(from)&&c.uci.slice(2,4)===to)){chooseSquare(to)}else{state.practiceError='Choose one of the marked legal squares.';render()}}});
document.addEventListener('pointercancel',()=>{if(boardDrag){clearBoardDrag();render()}});
document.addEventListener('keydown',ev=>{if(page!=='practice'||!ev.target.matches('.board.playable [data-square]'))return;const moves={ArrowRight:1,ArrowLeft:-1,ArrowDown:8,ArrowUp:-8};if(!(ev.key in moves))return;ev.preventDefault();const squares=[...document.querySelectorAll('.board.playable [data-square]')],i=squares.indexOf(ev.target),j=i+moves[ev.key];if(j>=0&&j<64&&(Math.abs(moves[ev.key])===8||Math.floor(i/8)===Math.floor(j/8)))squares[j].focus()});
window.addEventListener('hashchange',()=>D&&route());
fetch('data.json',{cache:'no-cache'}).then(r=>{if(!r.ok)throw new Error('Data not found');return r.json()}).then(data=>{D=data;route()}).catch(()=>{$('#content').innerHTML='<div class="empty-state"><h2>The game archive could not load.</h2><p>Serve this folder through a local HTTP server, then reload the page.</p><button class="btn" onclick="location.reload()" style="margin-top:15px">Reload</button></div>'});
